-- RoofGuard pitch templates per lead category; {co} = company name (Spark, 2026-10-03)
create table if not exists public.rg_pitch_templates (category text primary key, body text not null, updated_at timestamptz not null default now());
alter table public.rg_pitch_templates enable row level security;
create policy rg_pitch_templates_admin on public.rg_pitch_templates for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
on conflict (category) do nothing;